@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    <div class="security-option">
        <h3>Two-Factor Authentication</h3>
        <div class="checkbox-group">
            <input type="checkbox" id="twoFactor" @bind="security.TwoFactorEnabled" />
            <label for="twoFactor">Enable Two-Factor Authentication</label>
        </div>
        <button @onclick="SaveSecuritySettings" class="btn btn-primary">Save</button>
    </div>

    <div class="security-option">
        <h3>Change Password</h3>
        <form @onsubmit="HandlePasswordChange">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input type="password" id="currentPassword" @bind="currentPassword" class="form-control" />
            </div>
            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input type="password" id="newPassword" @bind="newPassword" class="form-control" />
            </div>
            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input type="password" id="confirmPassword" @bind="confirmPassword" class="form-control" />
            </div>
            <button type="submit" class="btn btn-primary">Change Password</button>
        </form>
    </div>

    <div class="security-option">
