@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models
@inject ISettingsService SettingsService

<section class="settings-section">
    <h4>Profile</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading profile…</p>
    }
    else
    {
        <div class="avatar-area mb-4">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" />
                }
                else
                {
                    <span class="avatar-placeholder">👤</span>
                }
            </div>
            <div class="avatar-url text-muted small mt-1">@_avatarUrl</div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">
                Discard Changes
            </button>
        </div>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">
                @_successMessage
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        ApplyProfile(profile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;

        _saving = false;
        _successMessage = "Profile saved successfully!";
        _ = DismissMessageAsync();
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _successMessage = null;
    }

    private async Task DismissMessageAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

.settings-section {
    padding: 1.5rem 2rem;
    max-width: 700px;
}

.settings-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
    color: #212529;
}

.avatar-area {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #dee2e6;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models
@inject ISettingsService SettingsService

<section class="settings-section">
    <h4>Notifications</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading preferences…</p>
    }
    else
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_emailNotifications" />
                    <span class="form-check-label">Email Notifications</span>
                </label>
                <span class="text-muted small">Receive updates via email</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_pushNotifications" />
                    <span class="form-check-label">Push Notifications</span>
                </label>
                <span class="text-muted small">Receive push alerts on your devices</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_weeklyDigest" />
                    <span class="form-check-label">Weekly Digest</span>
                </label>
                <span class="text-muted small">Get a summary of activity each week</span>
            </div>
        </div>

        <hr />

        <h6>Muted Channels</h6>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var isMuted = _mutedChannels.Contains(channel);
                <label class="form-check channel-item">
                    <input class="form-check-input" type="checkbox"
                           checked="@isMuted"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <span class="form-check-label">@channel</span>
                </label>
            }
        </div>

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Preferences")
            </button>
        </div>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">
                @_successMessage
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private static readonly string[] _allChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _successMessage = "Notification preferences saved!";
        _ = DismissMessageAsync();
    }

    private async Task DismissMessageAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

