@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models
@inject ISettingsService SettingsService

<section class="settings-section">
    <h4>Notifications</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading preferences…</p>
    }
    else
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_emailNotifications" />
                    <span class="form-check-label">Email Notifications</span>
                </label>
                <span class="text-muted small">Receive updates via email</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_pushNotifications" />
                    <span class="form-check-label">Push Notifications</span>
                </label>
                <span class="text-muted small">Receive push alerts on your devices</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_weeklyDigest" />
                    <span class="form-check-label">Weekly Digest</span>
                </label>
                <span class="text-muted small">Get a summary of activity each week</span>
            </div>
        </div>

        <hr />

        <h6>Muted Channels</h6>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var isMuted = _mutedChannels.Contains(channel);
                <label class="form-check channel-item">
                    <input class="form-check-input" type="checkbox"
                           checked="@isMuted"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <span class="form-check-label">@channel</span>
                </label>
            }
        </div>

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Preferences")
            </button>
        </div>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">
                @_successMessage
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private static readonly string[] _allChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _successMessage = "Notification preferences saved!";
        _ = DismissMessageAsync();
    }

    private async Task DismissMessageAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

