@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models
@inject ISettingsService SettingsService

<div class="password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span>🔑 Change Password</span>
        <span class="toggle-icon">@(_expanded ? "▲" : "▼")</span>
    </button>

    @if (_expanded)
    {
