@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models

<div class="sessions-area">
    <h6>Active Sessions</h6>
    <table class="table table-hover">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            @if (_confirmingSessionId == session.Id)
                            {
                                <span class="confirm-prompt">
                                    Revoke?
                                    <button class="btn btn-sm btn-danger" @onclick="() => ConfirmRevokeAsync(session.Id)">
                                        Yes
                                    </button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">
                                        No
                                    </button>
                                </span>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session.Id)">
                                    Revoke
                                </button>
                            }
                        }
                        else
                        {
                            <span class="badge bg-success">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId) => _confirmingSessionId = sessionId;

    private void CancelRevoke() => _confirmingSessionId = null;

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

.sessions-area {
    margin-top: 1.5rem;
}

.sessions-area h6 {
    margin-bottom: 1rem;
    font-weight: 600;
}

.confirm-prompt {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.85rem;
    font-weight: 500;
    color: #dc3545;
    animation: fadeIn 0.2s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

