@namespace sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Models
@inject ISettingsService SettingsService

<section class="settings-section">
    <h4>Appearance</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        <div class="mb-4">
            <label class="form-label fw-medium">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var theme in _themes)
                {
                    <label class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span class="form-check-label">@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-medium">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var size in _fontSizes)
                {
                    <label class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span class="form-check-label">@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="mb-4">
            <label class="form-label fw-medium">Language</label>
            <select class="form-select" style="max-width: 250px;"
                    @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang.Key">@lang.Value</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <label class="form-check form-switch">
                <input class="form-check-input" type="checkbox" @bind="_compactMode" />
                <span class="form-check-label fw-medium">Compact Mode</span>
            </label>
            <span class="text-muted small d-block">Reduce spacing and padding throughout the UI</span>
        </div>

        <div class="preview-area mb-4">
            <h6>Live Preview</h6>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">
                    This is a preview of how your selected appearance settings will look.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">
                @_successMessage
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語"
    };

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _successMessage = "Appearance settings saved!";
        _ = DismissMessageAsync();
    }

    private async Task DismissMessageAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

.settings-section {
    padding: 1.5rem 2rem;
    max-width: 700px;
}

.settings-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
    color: #212529;
}

.preview-area h6 {
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.preview-box {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.preview-body {
    margin-bottom: 1rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid transparent;
    font-weight: 500;
    cursor: default;
    transition: all 0.3s ease;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-button {
    background: #0d6efd;
    color: #fff;
}

.preview-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-dark .preview-button {
    background: #4a90d9;
    color: #fff;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%);
    color: #495057;
}

.preview-system .preview-button {
    background: #6c757d;
    color: #fff;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-header {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-body {
    margin-bottom: 0.5rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

