toolArgs.file_text:
.settings-section {
    padding: 1.5rem 2rem;
    max-width: 700px;
}

.settings-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
    color: #212529;
}

.preview-area h6 {
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.preview-box {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.preview-body {
    margin-bottom: 1rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid transparent;
    font-weight: 500;
    cursor: default;
    transition: all 0.3s ease;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-button {
    background: #0d6efd;
    color: #fff;
}

.preview-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-dark .preview-button {
    background: #4a90d9;
    color: #fff;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%);
    color: #495057;
}

.preview-system .preview-button {
    background: #6c757d;
    color: #fff;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-header {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-body {
    margin-bottom: 0.5rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

