+    border-color: #333;
+}
+
+.preview-dark .preview-button {
+    background: #4a90d9;
+    color: #fff;
+}
+
+.preview-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%);
+    color: #495057;
+}
+
+.preview-system .preview-button {
+    background: #6c757d;
+    color: #fff;
+}
+
+/* Font size variants */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-header {
+    margin-bottom: 0.35rem;
+}
+
+.preview-compact .preview-body {
+    margin-bottom: 0.5rem;
+}
+
+.fade-in {
+    animation: fadeIn 0.3s ease-in;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-4px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+

arguments.file_text:
@page "/settings"
@using sv_59ff03f258a24ce2b692bad4433ffbeb.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    margin: -1rem -1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

.settings-content {
    flex: 1;
    overflow-y: auto;
}

